INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35651, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "地表の最上部を覆う、岩石が風化・分解してできた物質。植物の生育に必要な養分や水分を含む。", "primary_collocate": null, "pronunciation": "どじょう", "ipa": "dodʑoː", "syllable_count": 3, "sentences": [{"text": "熟練したソムリエは、グラス内で展開される鉱物的な輪郭や土壌由来の複雑な香気構造を解読し、視覚や嗅覚を超えた土地的コンテキストを味覚的に再構成する。", "target_word": "土壌", "complexity_tier": "T6", "furigana": "どじょう", "sentence_source": "mined"}, {"text": "経験豊富な農家は、広大な畑の土壌を丁寧に耕し、野菜の種を植える。", "target_word": "土壌", "complexity_tier": "T6", "furigana": "どじょう", "sentence_source": "mined"}, {"text": "この地域の土壌は酸性が強いです。", "target_word": "土壌", "complexity_tier": "T2", "furigana": "どじょう", "sentence_source": "generated"}, {"text": "研究者が畑の土壌を調べている。", "target_word": "土壌", "complexity_tier": "T3", "furigana": "どじょう", "sentence_source": "generated"}, {"text": "土壌に石灰をまいて、酸性を弱める。", "target_word": "土壌", "complexity_tier": "T3", "furigana": "どじょう", "sentence_source": "generated"}, {"text": "雨で土壌の養分が流れてしまった。", "target_word": "土壌", "complexity_tier": "T3", "furigana": "どじょう", "sentence_source": "generated"}, {"text": "汚染された土壌を入れ替える工事が始まった。", "target_word": "土壌", "complexity_tier": "T3", "furigana": "どじょう", "sentence_source": "generated"}, {"text": "土壌の水分を測る機械を使います。", "target_word": "土壌", "complexity_tier": "T2", "furigana": "どじょう", "sentence_source": "generated"}, {"text": "この土壌なら、茶の木がよく育つ。", "target_word": "土壌", "complexity_tier": "T3", "furigana": "どじょう", "sentence_source": "generated"}, {"text": "火山灰でできた土壌は水を通しやすい。", "target_word": "土壌", "complexity_tier": "T3", "furigana": "どじょう", "sentence_source": "generated"}], "morphological_forms": [{"form": "土壌汚染", "label": "派生"}, {"form": "土壌改良", "label": "派生"}, {"form": "土壌調査", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 風化した岩石でできた地表の層", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 5 words above tier T3 (max 3): ソムリエ (Zipf 3.22), 輪郭 (Zipf 3.38), 香気 (Zipf 2.11), 嗅覚 (Zipf 3.32), コンテキスト (Zipf 2.7)']::text[], 'b8d04a9d-d5d7-4df8-9866-8fa7af888021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
