INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36589, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "刺激に対して体が自然に示す応答や変化。", "primary_collocate": null, "pronunciation": "はんのう", "ipa": "hannoː", "syllable_count": 4, "sentences": [{"text": "これは心理学に基づいた人間の無意識の反応を利用したものだ。", "target_word": "反応", "complexity_tier": "T6", "furigana": "はんのう", "sentence_source": "mined"}, {"text": "修業の途上にある若きパン職人は、夜明け前の凛とした空気が張り詰めるアトリエにて、野生の酵母が織りなす微細かつ劇的な化学反応と黙々と格闘していた。", "target_word": "反応", "complexity_tier": "T6", "furigana": "はんのう", "sentence_source": "mined"}, {"text": "薬に対する反応には、個人差がある。", "target_word": "反応", "complexity_tier": "T3", "furigana": "はんのう", "sentence_source": "generated"}, {"text": "医者は患者の反応を注意深く見ている。", "target_word": "反応", "complexity_tier": "T3", "furigana": "はんのう", "sentence_source": "generated"}, {"text": "彼女は冷たい水に敏感に反応した。", "target_word": "反応", "complexity_tier": "T3", "furigana": "はんのう", "sentence_source": "generated"}, {"text": "体が花粉に反応して、くしゃみが出る。", "target_word": "反応", "complexity_tier": "T3", "furigana": "はんのう", "sentence_source": "generated"}, {"text": "新しい薬を飲んでも、反応がなかった。", "target_word": "反応", "complexity_tier": "T3", "furigana": "はんのう", "sentence_source": "generated"}, {"text": "検査の結果、体に強い反応が出た。", "target_word": "反応", "complexity_tier": "T3", "furigana": "はんのう", "sentence_source": "generated"}, {"text": "光への反応を調べる実験を行った。", "target_word": "反応", "complexity_tier": "T3", "furigana": "はんのう", "sentence_source": "generated"}, {"text": "反応は人によってちがいます。", "target_word": "反応", "complexity_tier": "T2", "furigana": "はんのう", "sentence_source": "generated"}], "morphological_forms": [{"form": "反応する", "label": "活用"}, {"form": "反応した", "label": "活用"}, {"form": "反応しない", "label": "活用"}, {"form": "化学反応", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 刺激に対して体が示す自然な応答", "collocate_grounding": {"status": "no_sou