INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52156, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "穀物などを細かく砕いて作った粉末。", "primary_collocate": null, "pronunciation": "こな", "ipa": "kona", "syllable_count": 2, "sentences": [{"text": "まず、良質な全粒粉のパンを用意し、その多孔質な表面にピーナッツバターを均一に塗る。", "target_word": "粉", "complexity_tier": "T6", "furigana": "こな", "sentence_source": "mined"}, {"text": "水温と室温をミリ単位で制御し、小麦粉と水のみを混ぜ合わせる行為は、単なる調理の域を超え、微生物の生態系を育む科学的な実験とも呼応する。", "target_word": "粉", "complexity_tier": "T6", "furigana": "こな", "sentence_source": "mined"}, {"text": "そば粉で作った麺は香りがいい。", "target_word": "粉", "complexity_tier": "T3", "furigana": "こな", "sentence_source": "generated"}, {"text": "米を細かく砕いて、粉にする。", "target_word": "粉", "complexity_tier": "T3", "furigana": "こな", "sentence_source": "generated"}, {"text": "石臼で豆を挽くと、細かい粉になる。", "target_word": "粉", "complexity_tier": "T3", "furigana": "こな", "sentence_source": "generated"}, {"text": "これは、麦から作った粉です。", "target_word": "粉", "complexity_tier": "T2", "furigana": "こな", "sentence_source": "generated"}, {"text": "粉をふるいにかけて、塊をなくす。", "target_word": "粉", "complexity_tier": "T3", "furigana": "こな", "sentence_source": "generated"}, {"text": "袋の中の粉が、床にこぼれてしまった。", "target_word": "粉", "complexity_tier": "T3", "furigana": "こな", "sentence_source": "generated"}, {"text": "粉が細かいほど、口当たりがなめらかだ。", "target_word": "粉", "complexity_tier": "T3", "furigana": "こな", "sentence_source": "generated"}, {"text": "白い粉が、台の上に舞い上がった。", "target_word": "粉", "complexity_tier": "T3", "furigana": "こな", "sentence_source": "generated"}], "morphological_forms": [{"form": "粉末", "label": "派生"}, {"form": "米粉", "label": "派生"}, {"form": "そば粉", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 穀物を細かく砕いてできた粉末", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude