INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52155, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "小麦などを細かくくだいたもの。", "primary_collocate": null, "pronunciation": "こな", "ipa": "kona", "syllable_count": 2, "sentences": [{"text": "粉と水を混ぜて、生地を作る。", "target_word": "粉", "complexity_tier": "T3", "furigana": "こな", "sentence_source": "generated"}, {"text": "母は粉をふるってから、卵を入れた。", "target_word": "粉", "complexity_tier": "T3", "furigana": "こな", "sentence_source": "generated"}, {"text": "パンを焼くために、粉を買ってきた。", "target_word": "粉", "complexity_tier": "T3", "furigana": "こな", "sentence_source": "generated"}, {"text": "粉が足りなくて、ケーキが作れない。", "target_word": "粉", "complexity_tier": "T3", "furigana": "こな", "sentence_source": "generated"}, {"text": "台に粉をまいて、生地をのばします。", "target_word": "粉", "complexity_tier": "T2", "furigana": "こな", "sentence_source": "generated"}, {"text": "小麦をひいて、粉にする工場を見学した。", "target_word": "粉", "complexity_tier": "T3", "furigana": "こな", "sentence_source": "generated"}, {"text": "手に粉がついて、白くなった。", "target_word": "粉", "complexity_tier": "T3", "furigana": "こな", "sentence_source": "generated"}, {"text": "粉の量をはかるのは、大切な作業だ。", "target_word": "粉", "complexity_tier": "T3", "furigana": "こな", "sentence_source": "generated"}, {"text": "この粉は、お好み焼きに使えます。", "target_word": "粉", "complexity_tier": "T2", "furigana": "こな", "sentence_source": "generated"}, {"text": "粉を入れすぎると、かたくなる。", "target_word": "粉", "complexity_tier": "T3", "furigana": "こな", "sentence_source": "generated"}], "morphological_forms": [{"form": "小麦粉", "label": "派生"}, {"form": "粉末", "label": "派生"}, {"form": "米粉", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 小麦などをくだいたもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8d04a9d-d5d7-4df8-9866-8fa7a