INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52200, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の美しさや芸術的な価値について考える学問や、そのような価値そのもの。", "primary_collocate": null, "pronunciation": "びがく", "ipa": "bigaku", "syllable_count": 3, "sentences": [{"text": "次いで、ラズベリー等のジャムを対になる片割れ、あるいは同一の切片上に重ね合わせる。\n\n甘味と塩気、滑らかさと顆粒感が口腔内で織りなす対照的なハーモニーは、単なる栄養補給の域を超え、短時間での認知機能回復をもたらし、合理性と美学が融合した食の営みとして完成する。", "target_word": "美学", "complexity_tier": "T6", "furigana": "びがく", "sentence_source": "mined"}, {"text": "すなわち、限られた特権階級のみに奉仕することを潔しとしない独占的な美学こそが、地上に降り立つトレンドの羅針盤としての役割を担い、現代のファッション産業における生態系を永続的に循環させているのである。", "target_word": "美学", "complexity_tier": "T6", "furigana": "びがく", "sentence_source": "mined"}, {"text": "大学で美学を学んでいる。", "target_word": "美学", "complexity_tier": "T3", "furigana": "びがく", "sentence_source": "generated"}, {"text": "美学の授業で、絵画について話し合った。", "target_word": "美学", "complexity_tier": "T3", "furigana": "びがく", "sentence_source": "generated"}, {"text": "彼は、美学の研究者として知られている。", "target_word": "美学", "complexity_tier": "T3", "furigana": "びがく", "sentence_source": "generated"}, {"text": "古い日本の建物には、独特の美学がある。", "target_word": "美学", "complexity_tier": "T3", "furigana": "びがく", "sentence_source": "generated"}, {"text": "美学は、美しさの意味を考える学問だ。", "target_word": "美学", "complexity_tier": "T3", "furigana": "びがく", "sentence_source": "generated"}, {"text": "この映画は、光と影の美学を描いている。", "target_word": "美学", "complexity_tier": "T3", "furigana": "びがく", "sentence_source": "generated"}, {"text": "美学を専攻する学生が、展覧会を開いた。", "target_word": "美学", "complexity_tier": "T3", "furigana": "びがく", "sentence_source": "generated"}, {"text": "簡素さに美学を見いだす考え方が広まった。", "target_word": "美学", "complexity_tier": "T3", "furigana": "びがく", "sentence_source": "generated"}], "morphological_forms": [{"form": "美学者", "label": "派生"}, {"form": "美学的", "label": "派生"}, {"form": "美学科", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 美を考える学問や芸術的な価値", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T4: 6 words above tier T4 (max 5): 片割れ (Zipf 2.88), 切片 (Zipf 1.86), 重ね合わ (Zipf 2.98), 塩気 (Zipf 2.57), 顆粒 (Zipf 2.99), 織りなす (Zipf 2.63)']::text[], 'b8d04a9d-d5d7-4df8-9866-8fa7af888021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
