INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51508, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "毎朝は、毎日の朝のことを指します。", "primary_collocate": null, "pronunciation": "まいあさ", "ipa": "maiasa", "syllable_count": 4, "sentences": [{"text": "毎朝の天気予報を確認し、気温や湿度に合わせて水を調整する。", "target_word": "毎朝", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "彼にとって、毎朝のこの作業は生活のリズムを作る重要な儀式となっている。", "target_word": "毎朝", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "毎朝の散歩が好きだ。", "target_word": "毎朝", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "毎朝が一番忙しいです。", "target_word": "毎朝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "忙しいのは毎朝だけだ。", "target_word": "毎朝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "毎朝のパンが楽しみです。", "target_word": "毎朝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "毎朝の準備に三十分かかります。", "target_word": "毎朝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "毎朝を静かに過ごすために、早く起きている。", "target_word": "毎朝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "祖父は毎朝の日課を一日も欠かしたことがない。", "target_word": "毎朝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毎朝の掃除を続けたおかげで、家がきれいになった。", "target_word": "毎朝", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 毎日の朝という時間を指す名詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2be93efe-4e71-4212-bdcd-2b2c6be69eec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_e