INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51507, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "abstract", "definition": "毎朝は、あさのことを言うよ。", "primary_collocate": null, "pronunciation": "まいあさ", "ipa": "maiasa", "syllable_count": 4, "sentences": [{"text": "毎朝走る。", "target_word": "毎朝", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "毎朝、牛乳を飲む。", "target_word": "毎朝", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "毎朝七時に起きます。", "target_word": "毎朝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟は毎朝顔を洗います。", "target_word": "毎朝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "毎朝、駅まで歩いて行く。", "target_word": "毎朝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "彼女は毎朝、庭の花に水をやっている。", "target_word": "毎朝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毎朝コーヒーを入れて、ゆっくり新聞を読む。", "target_word": "毎朝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毎朝早く起きるようになってから、体調がよくなった。", "target_word": "毎朝", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "毎朝同じ時間に家を出なければ、電車に間に合わない。", "target_word": "毎朝", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "子どものころ、毎朝母が起こしてくれた。", "target_word": "毎朝", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "副詞 | 毎日朝になると繰り返す様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2be93efe-4e71-4212-bdcd-2b2c6be69eec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EX