INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38769, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "数量や種類が多くて、足りないところがないこと。", "primary_collocate": null, "pronunciation": "ほうふ", "ipa": "hoːɸɯ", "syllable_count": 3, "sentences": [{"text": "経験豊富な農家は、広大な畑の土壌を丁寧に耕し、野菜の種を植える。", "target_word": "豊富な", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "日の出と共に目覚める鶏の健康こそが、栄養豊富な卵を産んでもらうための条件だからである。", "target_word": "豊富な", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "栄養豊富な朝食だ。", "target_word": "豊富な", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "経験豊富な先生です。", "target_word": "豊富な", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "この野菜はビタミン豊富です。", "target_word": "豊富", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "経験豊富な店員が相談に乗ってくれた。", "target_word": "豊富な", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "種類豊富なパンが、棚にずらりと並んでいる。", "target_word": "豊富な", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "話題豊富な彼との会話は、いつも楽しい。", "target_word": "豊富な", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "知識豊富な講師に質問できてよかった。", "target_word": "豊富な", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "経験豊富で落ち着いた人が、チームをまとめている。", "target_word": "豊富で", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [{"form": "豊富な", "label": "活用"}, {"form": "豊富に", "label": "活用"}, {"form": "豊富だ", "label": "活用"}, {"form": "豊富さ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形状詞 | 名詞に付き多く備わる様子を表す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2be93efe-4e71-4212-bdcd-2b2c6be69eec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLU