INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38768, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "ものがたくさんあること。", "primary_collocate": null, "pronunciation": "ほうふ", "ipa": "hoːɸɯ", "syllable_count": 3, "sentences": [{"text": "この町は魚が豊富だ。", "target_word": "豊富だ", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "資源が豊富な国だ。", "target_word": "豊富な", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "この店は品物が豊富です。", "target_word": "豊富", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "図書館には本が豊富にあります。", "target_word": "豊富に", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山には水が豊富に流れている。", "target_word": "豊富に", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "語彙が豊富な人は、説明がうまい。", "target_word": "豊富な", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "北の海は、豊富な魚で知られている。", "target_word": "豊富な", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "資料が豊富なので、調べものがはかどった。", "target_word": "豊富な", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "選べる料理が豊富にそろっていて、迷ってしまった。", "target_word": "豊富に", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "豊富な資金があっても、使い方を誤れば意味がない。", "target_word": "豊富な", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [{"form": "豊富な", "label": "活用"}, {"form": "豊富に", "label": "活用"}, {"form": "豊富だ", "label": "活用"}, {"form": "豊富さ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形状詞 | ものが数多くあって足りている様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T3: contains vocabulary far above tier T3: 誤れ (Zipf 1.98)']::text[], '2be93efe-4e71-4212-bdcd-2b2c6be69eec') ON CONFLICT (sense_id