INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51528, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "光を当てて、物や場所を明るく見せたり、はっきりと見えるようにする。", "primary_collocate": null, "pronunciation": "てらす", "ipa": "teɾasɯ", "syllable_count": 3, "sentences": [{"text": "夜が明け、太陽が農場を照らし始める朝、農家の男は鶏舎へと足を運ぶ。", "target_word": "照らし", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "木漏れ日がその頬を静かに照らす中、彼はただ黙々と、自らの内なる飢えと、この季節の恵みとを一体化させていくのである。", "target_word": "照らす", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "月が道を照らす。", "target_word": "照らす", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "朝日が海を照らします。", "target_word": "照らし", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夕日が山を赤く照らしている。", "target_word": "照らし", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月の光が静かな湖を照らした。", "target_word": "照らした", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太陽は、地球のすべてを照らしてくれる。", "target_word": "照らして", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雲が切れて、光が町じゅうを照らした。", "target_word": "照らした", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "星の光に照らされた雪原は、青白く輝いていた。", "target_word": "照らされた", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朝日に照らされる山の頂は、何よりも美しい景色だと言われている。", "target_word": "照らされる", "complexity_tier": "T5", "sentence_source": "generated"}], "morphological_forms": [{"form": "照らして", "label": "活用"}, {"form": "照らした", "label": "活用"}, {"form": "照らされる", "label": "活用"}, {"form": "照らさない", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 自然の光が当たって見えるようにする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2be93efe-4e71-4212-bdcd-2b2c6be69eec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51527, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "光を当てて、明るくすること。", "primary_collocate": null, "pronunciation": "てらす", "ipa": "teɾasɯ", "syllable_count": 3, "sentences": [{"text": "ライトで足元を照らす。", "target_word": "照らす", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "懐中電灯で暗い道を照らした。", "target_word": "照らした", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "電気スタンドが机を照らしている。", "target_word": "照らし", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "彼は暗い部屋をろうそくで照らした。", "target_word": "照らした", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "懐中電灯で箱の中を照らして、鍵を探した。", "target_word": "照らして", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "街灯が夜の道を明るく照らしていて、安心だ。", "target_word": "照らして", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "ステージの真ん中を、強い光が照らす。", "target_word": "照らす", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "車のライトが前の道を照らしてくれるので、夜でも運転できる。", "target_word": "照らして", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "暗い洞窟では、ヘッドライトで周りを照らさないと進めない。", "target_word": "照らさ", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "スマホの光で照らせば、床に落ちた鍵も見つかるだろう。", "target_word": "照らせ", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [{"form": "照らして", "label": "活用"}, {"form": "照らした", "label": "活用"}, {"form": "照らされる", "label": "活用"}, {"form": "照らさない", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 灯りで暗い所を明るくすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2be93efe-4e71-4212-bdcd-2b2c6be69eec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUD