INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51538, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "いくつかのものをまぜて、一つにまとめること。", "primary_collocate": null, "pronunciation": "まぜあわせる", "ipa": "mazeawaseɾɯ", "syllable_count": 6, "sentences": [{"text": "この時間帯に与える食べ物は、地元で採れた新鮮な穀物と野菜を混ぜ合わせたものだ。", "target_word": "混ぜ合わせ", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "水温と室温をミリ単位で制御し、小麦粉と水のみを混ぜ合わせる行為は、単なる調理の域を超え、微生物の生態系を育む科学的な実験とも呼応する。", "target_word": "混ぜ合わせる", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "粉と水を混ぜ合わせる。", "target_word": "混ぜ合わせる", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "卵と砂糖を混ぜ合わせます。", "target_word": "混ぜ合わせ", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "牛乳と卵をよく混ぜ合わせた。", "target_word": "混ぜ合わせた", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "ボウルで材料を混ぜ合わせてください。", "target_word": "混ぜ合わせて", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "混ぜ合わせた生地を、冷蔵庫で休ませる。", "target_word": "混ぜ合わせた", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塩と油を混ぜ合わせてから、野菜にかける。", "target_word": "混ぜ合わせて", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "材料をすべて混ぜ合わせれば、ソースの完成だ。", "target_word": "混ぜ合わせれ", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "よく混ぜ合わせられたカレーは、味が均一になる。", "target_word": "混ぜ合わせられた", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [{"form": "混ぜ合わせた", "label": "活用"}, {"form": "混ぜ合わせて", "label": "活用"}, {"form": "混ぜ合わせない", "label": "活用"}, {"form": "混ぜ合わせられる", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 材料を混ぜて一つにまとめること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2be93efe-4e71-4