INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51537, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "二つ以上のものをいっしょにして、一つのものにする。", "primary_collocate": null, "pronunciation": "まぜあわせる", "ipa": "mazeawaseɾɯ", "syllable_count": 6, "sentences": [{"text": "色を混ぜ合わせる。", "target_word": "混ぜ合わせる", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "二つの意見を混ぜ合わせた。", "target_word": "混ぜ合わせた", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "赤と青を混ぜ合わせると、紫になる。", "target_word": "混ぜ合わせる", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和と洋を混ぜ合わせた部屋が人気だ。", "target_word": "混ぜ合わせた", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "絵の具を混ぜ合わせて、好きな色を作った。", "target_word": "混ぜ合わせて", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "いろいろな音楽を混ぜ合わせて、新しい曲を作る。", "target_word": "混ぜ合わせて", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "古い技術と新しい技術を混ぜ合わせた製品だ。", "target_word": "混ぜ合わせた", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日本と外国の文化が混ぜ合わせられ、独特の街並みができた。", "target_word": "混ぜ合わせられ", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "二つの案を混ぜ合わせれば、みんなが納得するかもしれない。", "target_word": "混ぜ合わせれ", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "彼女は、いくつもの言葉を混ぜ合わせて、自分だけの詩を作っている。", "target_word": "混ぜ合わせて", "complexity_tier": "T5", "sentence_source": "generated"}], "morphological_forms": [{"form": "混ぜ合わせた", "label": "活用"}, {"form": "混ぜ合わせて", "label": "活用"}, {"form": "混ぜ合わせない", "label": "活用"}, {"form": "混ぜ合わせられる", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 異なるものを一つにまとめあげること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2be93efe-4e71-4212-bdcd-2b2c6be69eec') 