INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52250, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物をのせる平らな台。また、碁や将棋などに使う台。", "primary_collocate": null, "pronunciation": "ばん", "ipa": "baɴ", "syllable_count": 2, "sentences": [{"text": "指先を通じて伝わる生地の微妙な弾力や発酵の進行具合を唯一の羅針盤とし、彼は温度と湿度という変数を緻密に制御することで、微生物という目に見えぬパートナーとの静かなる対話を試みる。", "target_word": "盤", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "すなわち、限られた特権階級のみに奉仕することを潔しとしない独占的な美学こそが、地上に降り立つトレンドの羅針盤としての役割を担い、現代のファッション産業における生態系を永続的に循環させているのである。", "target_word": "盤", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "盤の上に駒を並べる。", "target_word": "盤", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "二人は盤を挟んで座った。", "target_word": "盤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "祖父は将棋の盤を大切にしている。", "target_word": "盤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盤が大きすぎて、机にのらない。", "target_word": "盤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "碁を打つ前に、盤をきれいに拭いた。", "target_word": "盤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盤の上の石を見れば、勝負の流れがわかる。", "target_word": "盤", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "木でできた古い盤は、傷だらけだが味がある。", "target_word": "盤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "対局が始まると、盤を囲む人たちは静かになった。", "target_word": "盤", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 碁や将棋で使う平らな台", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: 6 words above tier T2 (max 3): 指先 (Zipf 3.6), 弾力 (Zipf 3.23), 変数 (Zipf 3.63), 緻密 (Zipf 3.25), 微生物 (Zipf 3.52), 試みる (Zipf 3.53)','sentence 1 above tier T2: contains vocabulary far above tier T2: 潔し (Zipf 1.9)']::text[], '2be93efe-4e71-4212-bdcd-2b2c6be69eec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52249, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものを のせる たいらな だい。", "primary_collocate": null, "pronunciation": "ばん", "ipa": "baɴ", "syllable_count": 2, "sentences": [{"text": "盤の上に皿を置く。", "target_word": "盤", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "平らな盤に水を張る。", "target_word": "盤", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "花を盤に浮かべました。", "target_word": "盤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "石でできた盤の上で、粉をこねた。", "target_word": "盤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "重い器を盤にのせて、運びます。", "target_word": "盤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盤が平らでないと、器がぐらぐらする。", "target_word": "盤", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "店員は果物を大きな盤に並べて、客に見せた。", "target_word": "盤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盤の上にのせたろうそくが、風で消えてしまった。", "target_word": "盤", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "彫刻の入った古い盤は、茶道具をのせるために作られたそうだ。", "target_word": "盤", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "浅い盤に砂を敷き、その上に小さな石を並べて庭を作る。", "target_word": "盤", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | ものをのせるための平らな台", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T2: contains vocabulary far above tier T2: ぐらぐら (Zipf 2.27)','sentence 8 above tier T2: contains vocabulary far above tier T2: 茶道具 (Zipf 2.38)']::text[], '2be93efe-4e71-4212-bdcd-2b2c6be69eec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.