INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52252, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "判断や行動のよりどころとなる指針。", "primary_collocate": null, "pronunciation": "らしん", "ipa": "ɾaɕiɴ", "syllable_count": 3, "sentences": [{"text": "指先を通じて伝わる生地の微妙な弾力や発酵の進行具合を唯一の羅針盤とし、彼は温度と湿度という変数を緻密に制御することで、微生物という目に見えぬパートナーとの静かなる対話を試みる。", "target_word": "羅針", "complexity_tier": "T6", "furigana": "らしん", "sentence_source": "mined"}, {"text": "すなわち、限られた特権階級のみに奉仕することを潔しとしない独占的な美学こそが、地上に降り立つトレンドの羅針盤としての役割を担い、現代のファッション産業における生態系を永続的に循環させているのである。", "target_word": "羅針", "complexity_tier": "T6", "furigana": "らしん", "sentence_source": "mined"}, {"text": "信念こそが、迷う私にとって唯一の羅針だった。", "target_word": "羅針", "complexity_tier": "T4", "furigana": "らしん", "sentence_source": "generated"}, {"text": "この本が私の人生の羅針になった。", "target_word": "羅針", "complexity_tier": "T2", "furigana": "らしん", "sentence_source": "generated"}, {"text": "彼は羅針を失い、どの道へ進むべきか悩んだ。", "target_word": "羅針", "complexity_tier": "T4", "furigana": "らしん", "sentence_source": "generated"}, {"text": "祖母の言葉は今も私の羅針です。", "target_word": "羅針", "complexity_tier": "T2", "furigana": "らしん", "sentence_source": "generated"}, {"text": "明確な羅針がなければ、組織は迷走する。", "target_word": "羅針", "complexity_tier": "T4", "furigana": "らしん", "sentence_source": "generated"}, {"text": "理念を羅針として、会社は新しい事業を始めた。", "target_word": "羅針", "complexity_tier": "T3", "furigana": "らしん", "sentence_source": "generated"}, {"text": "若い頃に出会った師が、私に羅針を与えてくれた。", "target_word": "羅針", "complexity_tier": "T5", "furigana": "らしん", "sentence_source": "generated"}, {"text": "羅針のない旅は、不安でいっぱいだった。", "target_word": "羅針", "complexity_tier": "T3", "furigana": "らしん", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 判断のよりどころ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T3: contains vocabulary far above tier T3: 潔し (Zipf 1.9)']::text[], '5ed3d159-2f98-425e-96a9-d3ac547716a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52251, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "方位を示す磁石の針。", "primary_collocate": null, "pronunciation": "らしん", "ipa": "ɾaɕiɴ", "syllable_count": 3, "sentences": [{"text": "羅針は北を指す。", "target_word": "羅針", "complexity_tier": "T1", "furigana": "らしん", "sentence_source": "generated"}, {"text": "船長は羅針を見て進路を確かめた。", "target_word": "羅針", "complexity_tier": "T3", "furigana": "らしん", "sentence_source": "generated"}, {"text": "古い羅針は少し錆びています。", "target_word": "羅針", "complexity_tier": "T2", "furigana": "らしん", "sentence_source": "generated"}, {"text": "彼は小さな羅針を手のひらにのせた。", "target_word": "羅針", "complexity_tier": "T2", "furigana": "らしん", "sentence_source": "generated"}, {"text": "羅針が小刻みに震えて止まらない。", "target_word": "羅針", "complexity_tier": "T3", "furigana": "らしん", "sentence_source": "generated"}, {"text": "嵐の中で羅針が狂い、船は方向を見失った。", "target_word": "羅針", "complexity_tier": "T3", "furigana": "らしん", "sentence_source": "generated"}, {"text": "この箱には祖父の使った羅針が入っている。", "target_word": "羅針", "complexity_tier": "T3", "furigana": "らしん", "sentence_source": "generated"}, {"text": "羅針さえあれば、迷わずに北へ進める。", "target_word": "羅針", "complexity_tier": "T4", "furigana": "らしん", "sentence_source": "generated"}, {"text": "地図と羅針を持って山道を歩き出した。", "target_word": "羅針", "complexity_tier": "T3", "furigana": "らしん", "sentence_source": "generated"}, {"text": "羅針を磁石の近くに置いてはいけません。", "target_word": "羅針", "complexity_tier": "T3", "furigana": "らしん", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 方位を示す磁針", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ed3d159-2f98-425e-96a9-d3ac547716a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDE