INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51600, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "建物や木などが、ひっそりとその場所にある。", "primary_collocate": null, "pronunciation": "たたずむ", "ipa": "tatazumɯ", "syllable_count": 4, "sentences": [{"text": "森の奥深くに佇む、その赤いドアの小さな家は、かつて祖母が一人で暮らしていた場所だ。", "target_word": "佇む", "complexity_tier": "T6", "furigana": "たたずむ", "sentence_source": "mined"}, {"text": "しかし、窓辺に佇む幼き我が子の瞳は、白銀に覆われた庭先へと注がれ、抑えきれない生命の衝動に駆られていた。", "target_word": "佇む", "complexity_tier": "T6", "furigana": "たたずむ", "sentence_source": "mined"}, {"text": "湖のほとりに古い教会が佇んでいる。", "target_word": "佇んでいる", "complexity_tier": "T3", "furigana": "たたずんでいる", "sentence_source": "generated"}, {"text": "丘の上に桜が佇む。", "target_word": "佇む", "complexity_tier": "T1", "furigana": "たたずむ", "sentence_source": "generated"}, {"text": "霧の中に佇む城は、まるで絵のようだった。", "target_word": "佇む", "complexity_tier": "T3", "furigana": "たたずむ", "sentence_source": "generated"}, {"text": "海辺に佇む灯台が、夕日に赤く染まっている。", "target_word": "佇む", "complexity_tier": "T3", "furigana": "たたずむ", "sentence_source": "generated"}, {"text": "谷あいの村に、小さな木造の駅が佇んでいる。", "target_word": "佇んでいる", "complexity_tier": "T3", "furigana": "たたずんでいる", "sentence_source": "generated"}, {"text": "雪原に佇む一軒の山小屋を写真に撮った。", "target_word": "佇む", "complexity_tier": "T3", "furigana": "たたずむ", "sentence_source": "generated"}, {"text": "古い寺が静かに佇み、旅人を迎えてくれた。", "target_word": "佇み", "complexity_tier": "T3", "furigana": "たたずみ", "sentence_source": "generated"}, {"text": "通りに佇むその喫茶店は六十年続く。", "target_word": "佇む", "complexity_tier": "T3", "furigana": "たたずむ", "sentence_source": "generated"}], "morphological_forms": [{"form": "佇んでいる", "label": "活用"}, {"form": "佇んだ", "label": "活用"}, {"form": "佇み", "label": "活用"}, {"form": "佇まない", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 物がひっそりと在る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ed3d159-2f98-425e-96a9-d3ac547716a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51599, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人がその場にじっと立って動かずにいる。", "primary_collocate": null, "pronunciation": "たたずむ", "ipa": "tatazumɯ", "syllable_count": 4, "sentences": [{"text": "彼は改札の前で佇んだ。", "target_word": "佇んだ", "complexity_tier": "T2", "furigana": "たたずんだ", "sentence_source": "generated"}, {"text": "母は玄関に佇み、帰りを待っていた。", "target_word": "佇み", "complexity_tier": "T3", "furigana": "たたずみ", "sentence_source": "generated"}, {"text": "雨の中、彼女は傘もささずに佇んでいる。", "target_word": "佇んでいる", "complexity_tier": "T3", "furigana": "たたずんでいる", "sentence_source": "generated"}, {"text": "彼は何も言えず、その場に佇むしかなかった。", "target_word": "佇む", "complexity_tier": "T3", "furigana": "たたずむ", "sentence_source": "generated"}, {"text": "墓の前に佇む老人は、じっと目を閉じていた。", "target_word": "佇む", "complexity_tier": "T3", "furigana": "たたずむ", "sentence_source": "generated"}, {"text": "道の真ん中に佇んでいると、車に注意された。", "target_word": "佇んで", "complexity_tier": "T4", "furigana": "たたずんで", "sentence_source": "generated"}, {"text": "声をかけられても、彼はただ佇んでいた。", "target_word": "佇んでいた", "complexity_tier": "T4", "furigana": "たたずんでいた", "sentence_source": "generated"}, {"text": "先生は教室の入り口で、しばらく佇んでいた。", "target_word": "佇んでいた", "complexity_tier": "T3", "furigana": "たたずんでいた", "sentence_source": "generated"}, {"text": "夜の海を前にして、私は一人静かに佇んだ。", "target_word": "佇んだ", "complexity_tier": "T3", "furigana": "たたずんだ", "sentence_source": "generated"}, {"text": "佇む人影が、夕暮れの駅に長く伸びていた。", "target_word": "佇む", "complexity_tier": "T3", "furigana": "たたずむ", "sentence_source": "generated"}], "morphological_forms": [{"form": "佇んでいる", "label": "活用"}, {"form": "佇んだ", "label": "活用"}, {"form": "佇み", "label": "活用"}, {"form": "佇まない", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 人が立ち止まる", "collocate_grounding": {"status": "no_source", "reason": "no col