INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36777, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "家に付属し、草木を植えて手入れされた屋外の空間。", "primary_collocate": null, "pronunciation": "にわ", "ipa": "ɲiwa", "syllable_count": 2, "sentences": [{"text": "色褪せた外壁や苔むした庭は、過ぎ去った長い年月を静かに物語っている。", "target_word": "庭", "complexity_tier": "T6", "furigana": "にわ", "sentence_source": "mined"}, {"text": "庭の片隅に、子供のための遊び小屋を建てる計画が持ち上がった。", "target_word": "庭", "complexity_tier": "T6", "furigana": "にわ", "sentence_source": "mined"}, {"text": "祖父は毎朝、庭の草花に水をやる。", "target_word": "庭", "complexity_tier": "T2", "furigana": "にわ", "sentence_source": "generated"}, {"text": "広い庭を持つ家に引っ越すのが夢だ。", "target_word": "庭", "complexity_tier": "T3", "furigana": "にわ", "sentence_source": "generated"}, {"text": "手入れされた庭には、季節の花が咲いている。", "target_word": "庭", "complexity_tier": "T4", "furigana": "にわ", "sentence_source": "generated"}, {"text": "雨上がりの庭は、土の香りが濃くなる。", "target_word": "庭", "complexity_tier": "T3", "furigana": "にわ", "sentence_source": "generated"}, {"text": "縁側から庭を眺めるのが、父の楽しみです。", "target_word": "庭", "complexity_tier": "T3", "furigana": "にわ", "sentence_source": "generated"}, {"text": "庭に面した部屋は、昼でも明るい。", "target_word": "庭", "complexity_tier": "T3", "furigana": "にわ", "sentence_source": "generated"}, {"text": "この旅館の庭は、四季折々の景色で知られている。", "target_word": "庭", "complexity_tier": "T4", "furigana": "にわ", "sentence_source": "generated"}, {"text": "庭で育てたトマトを、隣人におすそ分けした。", "target_word": "庭", "complexity_tier": "T3", "furigana": "にわ", "sentence_source": "generated"}], "morphological_forms": [{"form": "庭園", "label": "派生"}, {"form": "裏庭", "label": "派生"}, {"form": "中庭", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 手入れされた屋外の庭", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v