INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36776, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "家のそとにある、子どもが遊ぶ広い場所。", "primary_collocate": null, "pronunciation": "にわ", "ipa": "ɲiwa", "syllable_count": 2, "sentences": [{"text": "庭で犬が遊びます。", "target_word": "庭", "complexity_tier": "T2", "furigana": "にわ", "sentence_source": "generated"}, {"text": "うちの庭に花が咲きました。", "target_word": "庭", "complexity_tier": "T2", "furigana": "にわ", "sentence_source": "generated"}, {"text": "庭は広くて、きれいです。", "target_word": "庭", "complexity_tier": "T2", "furigana": "にわ", "sentence_source": "generated"}, {"text": "私は庭でサッカーをしました。", "target_word": "庭", "complexity_tier": "T2", "furigana": "にわ", "sentence_source": "generated"}, {"text": "庭に朝顔の種をまきます。", "target_word": "庭", "complexity_tier": "T2", "furigana": "にわ", "sentence_source": "generated"}, {"text": "庭の木に、小さな鳥がとまっている。", "target_word": "庭", "complexity_tier": "T3", "furigana": "にわ", "sentence_source": "generated"}, {"text": "庭の花に水をあげるのは私の仕事です。", "target_word": "庭", "complexity_tier": "T3", "furigana": "にわ", "sentence_source": "generated"}, {"text": "雨がやんだら、庭で遊んでもいいですか。", "target_word": "庭", "complexity_tier": "T4", "furigana": "にわ", "sentence_source": "generated"}, {"text": "庭には、ブランコと滑り台があります。", "target_word": "庭", "complexity_tier": "T2", "furigana": "にわ", "sentence_source": "generated"}, {"text": "庭にいる猫は、隣の家の猫です。", "target_word": "庭", "complexity_tier": "T2", "furigana": "にわ", "sentence_source": "generated"}], "morphological_forms": [{"form": "庭園", "label": "派生"}, {"form": "裏庭", "label": "派生"}, {"form": "中庭", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 遊び場になる家の外", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ed3d159-2f98-425e-96a9-d3ac547716a9') ON CO