INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36259, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "property", "definition": "基準や予想などと一致せず、別のものである。", "primary_collocate": null, "pronunciation": "ことなる", "ipa": "kotonaɾɯ", "syllable_count": 4, "sentences": [{"text": "現実的な設計図とは異なるが、その絵には彼が求める理想の世界が詰まっている。", "target_word": "異なる", "complexity_tier": "T6", "furigana": "ことなる", "sentence_source": "mined"}, {"text": "特に多色印刷の場合、色ごとに異なる版木を使い分ける必要があり、職人たちの高度な技術と協力が不可欠です。", "target_word": "異なる", "complexity_tier": "T6", "furigana": "ことなる", "sentence_source": "mined"}, {"text": "結果は予想と異なっていた。", "target_word": "異なっていた", "complexity_tier": "T3", "furigana": "ことなっていた", "sentence_source": "generated"}, {"text": "私の意見は、彼の考えとは異なる。", "target_word": "異なる", "complexity_tier": "T3", "furigana": "ことなる", "sentence_source": "generated"}, {"text": "実際の味は、写真とは異なりました。", "target_word": "異なり", "complexity_tier": "T2", "furigana": "ことなり", "sentence_source": "generated"}, {"text": "説明が事実と異なる場合は、訂正してください。", "target_word": "異なる", "complexity_tier": "T3", "furigana": "ことなる", "sentence_source": "generated"}, {"text": "見た目と異なり、この箱はとても軽い。", "target_word": "異なり", "complexity_tier": "T3", "furigana": "ことなり", "sentence_source": "generated"}, {"text": "事前の報告と異なる点が、いくつか見つかった。", "target_word": "異なる", "complexity_tier": "T3", "furigana": "ことなる", "sentence_source": "generated"}, {"text": "計画と異なる方向に話が進んでしまった。", "target_word": "異なる", "complexity_tier": "T3", "furigana": "ことなる", "sentence_source": "generated"}, {"text": "彼の証言は、以前の発言と異なるものだった。", "target_word": "異なる", "complexity_tier": "T3", "furigana": "ことなる", "sentence_source": "generated"}], "morphological_forms": [{"form": "異なる", "label": "活用"}, {"form": "異なった", "label": "活用"}, {"form": "異なって", "label": "活用"}, {"form": "異ならない", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 基準と一致しない", "collocate_grounding": {"st