INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51660, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "木の葉の間から地面や体に落ちる、まだらな日の光。", "primary_collocate": null, "pronunciation": "こもれび", "ipa": "komoɾebi", "syllable_count": 4, "sentences": [{"text": "最終的に、その雰囲気を取り入れた、木漏れ日が差し込む開放的な小屋が完成し、家族の新たな憩いの場となった。", "target_word": "木漏れ日", "complexity_tier": "T6", "furigana": "こもれび", "sentence_source": "mined"}, {"text": "木漏れ日がその頬を静かに照らす中、彼はただ黙々と、自らの内なる飢えと、この季節の恵みとを一体化させていくのである。", "target_word": "木漏れ日", "complexity_tier": "T6", "furigana": "こもれび", "sentence_source": "mined"}, {"text": "木漏れ日が地面に揺れている。", "target_word": "木漏れ日", "complexity_tier": "T3", "furigana": "こもれび", "sentence_source": "generated"}, {"text": "木漏れ日の下で、本を読んだ。", "target_word": "木漏れ日", "complexity_tier": "T2", "furigana": "こもれび", "sentence_source": "generated"}, {"text": "公園のベンチは、木漏れ日で温かかった。", "target_word": "木漏れ日", "complexity_tier": "T3", "furigana": "こもれび", "sentence_source": "generated"}, {"text": "木漏れ日を浴びながら、私たちは森を歩いた。", "target_word": "木漏れ日", "complexity_tier": "T3", "furigana": "こもれび", "sentence_source": "generated"}, {"text": "きらきら光る木漏れ日が、水面に映っていた。", "target_word": "木漏れ日", "complexity_tier": "T3", "furigana": "こもれび", "sentence_source": "generated"}, {"text": "木漏れ日のまだら模様が、白いシャツに落ちた。", "target_word": "木漏れ日", "complexity_tier": "T3", "furigana": "こもれび", "sentence_source": "generated"}, {"text": "木漏れ日に包まれて、猫はぐっすり眠っている。", "target_word": "木漏れ日", "complexity_tier": "T4", "furigana": "こもれび", "sentence_source": "generated"}, {"text": "柔らかな木漏れ日は、朝の森の宝物だ。", "target_word": "木漏れ日", "complexity_tier": "T3", "furigana": "こもれび", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 葉の間から落ちる光", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ed3d159-2f98-425e-96a9-d3ac547716a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51659, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "木の葉のすきまから、すじになって差してくる太陽の光。", "primary_collocate": null, "pronunciation": "こもれび", "ipa": "komoɾebi", "syllable_count": 4, "sentences": [{"text": "木漏れ日が差し込む。", "target_word": "木漏れ日", "complexity_tier": "T1", "furigana": "こもれび", "sentence_source": "generated"}, {"text": "窓の外の木から、木漏れ日がこぼれる。", "target_word": "木漏れ日", "complexity_tier": "T3", "furigana": "こもれび", "sentence_source": "generated"}, {"text": "森の入り口から、木漏れ日が一筋差し込んでいた。", "target_word": "木漏れ日", "complexity_tier": "T3", "furigana": "こもれび", "sentence_source": "generated"}, {"text": "風が吹くたびに、木漏れ日が形を変える。", "target_word": "木漏れ日", "complexity_tier": "T3", "furigana": "こもれび", "sentence_source": "generated"}, {"text": "朝の木漏れ日が、静かな部屋を明るくした。", "target_word": "木漏れ日", "complexity_tier": "T3", "furigana": "こもれび", "sentence_source": "generated"}, {"text": "木漏れ日の中を歩くと、気分が安らぐ。", "target_word": "木漏れ日", "complexity_tier": "T3", "furigana": "こもれび", "sentence_source": "generated"}, {"text": "高い杉の間から、木漏れ日が降りそそぐ。", "target_word": "木漏れ日", "complexity_tier": "T3", "furigana": "こもれび", "sentence_source": "generated"}, {"text": "カーテン越しの木漏れ日で、私は目を覚ました。", "target_word": "木漏れ日", "complexity_tier": "T3", "furigana": "こもれび", "sentence_source": "generated"}, {"text": "木漏れ日が揺れる様子を、カメラで撮った。", "target_word": "木漏れ日", "complexity_tier": "T3", "furigana": "こもれび", "sentence_source": "generated"}, {"text": "木漏れ日は、夏より秋のほうがやさしい。", "target_word": "木漏れ日", "complexity_tier": "T3", "furigana": "こもれび", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 葉の間から差す光", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ed3d159-2f98-425e-96a9-d3ac5477