INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38647, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の最後の段階。それ以上先がないこと。", "primary_collocate": null, "pronunciation": "さいしゅう", "ipa": "saiɕɯː", "syllable_count": 4, "sentences": [{"text": "最終的に、その雰囲気を取り入れた、木漏れ日が差し込む開放的な小屋が完成し、家族の新たな憩いの場となった。", "target_word": "最終", "complexity_tier": "T6", "furigana": "さいしゅう", "sentence_source": "mined"}, {"text": "最終段階のベーキングでは、高温の蒸気と共に膨張した生地が、黄金色の硬質で脆いクラストを纏い、内部は瑞々しくも弾力に富んだクラムへと昇華する。", "target_word": "最終", "complexity_tier": "T6", "furigana": "さいしゅう", "sentence_source": "mined"}, {"text": "最終の判断は、社長が下すことになっている。", "target_word": "最終", "complexity_tier": "T3", "furigana": "さいしゅう", "sentence_source": "generated"}, {"text": "工事は最終の段階に入って、もうすぐ終わる。", "target_word": "最終", "complexity_tier": "T3", "furigana": "さいしゅう", "sentence_source": "generated"}, {"text": "ここが最終の確認です。", "target_word": "最終", "complexity_tier": "T3", "furigana": "さいしゅう", "sentence_source": "generated"}, {"text": "交渉は最終の段階に近づいている。", "target_word": "最終", "complexity_tier": "T3", "furigana": "さいしゅう", "sentence_source": "generated"}, {"text": "最終的な決定は、まだ出ていない。", "target_word": "最終", "complexity_tier": "T3", "furigana": "さいしゅう", "sentence_source": "generated"}, {"text": "最終の仕上げは、みんなで行った。", "target_word": "最終", "complexity_tier": "T3", "furigana": "さいしゅう", "sentence_source": "generated"}, {"text": "長い会議は、最終の話し合いで意見がまとまった。", "target_word": "最終", "complexity_tier": "T3", "furigana": "さいしゅう", "sentence_source": "generated"}, {"text": "最終の責任は、私が取ります。", "target_word": "最終", "complexity_tier": "T3", "furigana": "さいしゅう", "sentence_source": "generated"}], "morphological_forms": [{"form": "最終的", "label": "派生"}, {"form": "最終段階", "label": "派生"}, {"form": "最終案", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物事が終わる直前の最後の段階", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 3 words above tier T1 (max 2): 木漏れ日 (Zipf 2.6), 差し込む (Zipf 3.05), 憩い (Zipf 3.01)','sentence 1 above tier T1: contains vocabulary far above tier T1: ベーキング (Zipf 1.24), クラスト (Zipf 2.0), 瑞々しく (Zipf 1.76), クラム (Zipf 2.34)']::text[], 'a446fd76-121f-4288-b5cb-047371155a2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38646, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "いちばんおわり。", "primary_collocate": null, "pronunciation": "さいしゅう", "ipa": "saiɕɯː", "syllable_count": 4, "sentences": [{"text": "最終の電車に、ぎりぎりで乗れた。", "target_word": "最終", "complexity_tier": "T3", "furigana": "さいしゅう", "sentence_source": "generated"}, {"text": "大会の最終の日は、雨だった。", "target_word": "最終", "complexity_tier": "T3", "furigana": "さいしゅう", "sentence_source": "generated"}, {"text": "列の最終の人が、手をあげた。", "target_word": "最終", "complexity_tier": "T3", "furigana": "さいしゅう", "sentence_source": "generated"}, {"text": "最終のバスは、夜十一時に出る。", "target_word": "最終", "complexity_tier": "T3", "furigana": "さいしゅう", "sentence_source": "generated"}, {"text": "ドラマの最終の回を、家族で見た。", "target_word": "最終", "complexity_tier": "T3", "furigana": "さいしゅう", "sentence_source": "generated"}, {"text": "最終のランナーが、ゴールに入った。", "target_word": "最終", "complexity_tier": "T3", "furigana": "さいしゅう", "sentence_source": "generated"}, {"text": "最終の電車まで、駅で待った。", "target_word": "最終", "complexity_tier": "T3", "furigana": "さいしゅう", "sentence_source": "generated"}, {"text": "この列車が、今日の最終です。", "target_word": "最終", "complexity_tier": "T3", "furigana": "さいしゅう", "sentence_source": "generated"}, {"text": "最終の一人が、教室を出ていった。", "target_word": "最終", "complexity_tier": "T3", "furigana": "さいしゅう", "sentence_source": "generated"}, {"text": "最終の便に間に合わず、駅で泊まった。", "target_word": "最終", "complexity_tier": "T3", "furigana": "さいしゅう", "sentence_source": "generated"}], "morphological_forms": [{"form": "最終日", "label": "派生"}, {"form": "最終回", "label": "派生"}, {"form": "最終便", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 順番のいちばん後ろにくるもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NU