INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51994, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "困難な目標や課題に向かって、積極的に立ち向かい、成し遂げようとすること。", "primary_collocate": null, "pronunciation": "いどむ", "ipa": "idomɯ", "syllable_count": 3, "sentences": [{"text": "不確実性の高い技術的課題に挑む起業家に対し、リスクマネーを供給することで、彼らは市場の失敗を補完し、破壊的なイノベーションの萌芽を育むのである。", "target_word": "挑む", "complexity_tier": "T6", "furigana": "いどむ", "sentence_source": "mined"}, {"text": "凍てつく空気の中、ボタンを一つひとつ留める仕草には、未知の領域へ挑む戦士のような厳粛ささえ漂っていた。", "target_word": "挑む", "complexity_tier": "T6", "furigana": "いどむ", "sentence_source": "mined"}, {"text": "彼は新しい記録に挑んでいる。", "target_word": "挑んでいる", "complexity_tier": "T3", "furigana": "いどむ", "sentence_source": "generated"}, {"text": "私は来年、難しい試験に挑むつもりだ。", "target_word": "挑む", "complexity_tier": "T3", "furigana": "いどむ", "sentence_source": "generated"}, {"text": "目標へ向かって、彼は挑み続けた。", "target_word": "挑み", "complexity_tier": "T3", "furigana": "いどむ", "sentence_source": "generated"}, {"text": "挑む気持ちが、人を強くする。", "target_word": "挑む", "complexity_tier": "T3", "furigana": "いどむ", "sentence_source": "generated"}, {"text": "彼女は大きな課題に挑み、やり遂げた。", "target_word": "挑み", "complexity_tier": "T3", "furigana": "いどむ", "sentence_source": "generated"}, {"text": "仲間と挑んだ山は、とても高かった。", "target_word": "挑んだ", "complexity_tier": "T3", "furigana": "いどむ", "sentence_source": "generated"}, {"text": "失敗を恐れずに挑むことが大切だ。", "target_word": "挑む", "complexity_tier": "T3", "furigana": "いどむ", "sentence_source": "generated"}, {"text": "解決できない問題を前に、挑む研究者がいる。", "target_word": "挑む", "complexity_tier": "T3", "furigana": "いどむ", "sentence_source": "generated"}], "morphological_forms": [{"form": "挑んだ", "label": "活用"}, {"form": "挑んで", "label": "活用"}, {"form": "挑まれる", "label": "活用"}, {"form": "挑戦", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 難しい目標や課題へ向かって立ち向かう", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a446fd76-121f-4288-b5cb-047371155a2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51993, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "むずかしいことに、がんばって立ちむかうこと。", "primary_collocate": null, "pronunciation": "いどむ", "ipa": "idomɯ", "syllable_count": 3, "sentences": [{"text": "弟は強い相手に勝負を挑んだ。", "target_word": "挑んだ", "complexity_tier": "T3", "furigana": "いどむ", "sentence_source": "generated"}, {"text": "彼は私にチェスの試合を挑んできた。", "target_word": "挑んで", "complexity_tier": "T3", "furigana": "いどむ", "sentence_source": "generated"}, {"text": "新人が、チャンピオンに挑む。", "target_word": "挑む", "complexity_tier": "T3", "furigana": "いどむ", "sentence_source": "generated"}, {"text": "王者に挑む日が、ついに来た。", "target_word": "挑む", "complexity_tier": "T3", "furigana": "いどむ", "sentence_source": "generated"}, {"text": "一人で大きな相手に挑むには、勇気がいる。", "target_word": "挑む", "complexity_tier": "T3", "furigana": "いどむ", "sentence_source": "generated"}, {"text": "彼女は先輩に、何度も挑んだ。", "target_word": "挑んだ", "complexity_tier": "T3", "furigana": "いどむ", "sentence_source": "generated"}, {"text": "負けた男が、もう一度挑んできた。", "target_word": "挑んで", "complexity_tier": "T3", "furigana": "いどむ", "sentence_source": "generated"}, {"text": "挑まれた私は、受けて立った。", "target_word": "挑まれ", "complexity_tier": "T3", "furigana": "いどむ", "sentence_source": "generated"}, {"text": "そのボクサーは、世界王者に挑むことになった。", "target_word": "挑む", "complexity_tier": "T3", "furigana": "いどむ", "sentence_source": "generated"}, {"text": "私に挑むなら、本気で来なさい。", "target_word": "挑む", "complexity_tier": "T3", "furigana": "いどむ", "sentence_source": "generated"}], "morphological_forms": [{"form": "挑んだ", "label": "活用"}, {"form": "挑まれる", "label": "活用"}, {"form": "挑んできた", "label": "活用"}, {"form": "挑戦", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 相手に勝負や試合を申し込む", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a446fd76-121f-4288-b5cb-047371155a2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52120, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "顔の側面で、口の上下にあるふくらんだ部分。", "primary_collocate": null, "pronunciation": "ほお", "ipa": "hoː", "syllable_count": 2, "sentences": [{"text": "木漏れ日がその頬を静かに照らす中、彼はただ黙々と、自らの内なる飢えと、この季節の恵みとを一体化させていくのである。", "target_word": "頬", "complexity_tier": "T6", "furigana": "ほお", "sentence_source": "mined"}, {"text": "苛烈な寒風が頬を打つ外の世界へと、無垢な好奇心を携えて駆け出していくその背中には、人間が本来備えている、過酷な環境をも楽しみへと変貌させる逞しさが凝縮されていたのである。", "target_word": "頬", "complexity_tier": "T6", "furigana": "ほお", "sentence_source": "mined"}, {"text": "冷たい風が、頬に当たった。", "target_word": "頬", "complexity_tier": "T3", "furigana": "ほお", "sentence_source": "generated"}, {"text": "母は私の頬にそっと手を当てた。", "target_word": "頬", "complexity_tier": "T3", "furigana": "ほお", "sentence_source": "generated"}, {"text": "頬をなでる風が、気持ちいい。", "target_word": "頬", "complexity_tier": "T3", "furigana": "ほお", "sentence_source": "generated"}, {"text": "雪が頬に落ちて、すぐに溶けた。", "target_word": "頬", "complexity_tier": "T3", "furigana": "ほお", "sentence_source": "generated"}, {"text": "寒い朝は、頬が冷たくなる。", "target_word": "頬", "complexity_tier": "T3", "furigana": "ほお", "sentence_source": "generated"}, {"text": "太陽の光が、頬を温めてくれた。", "target_word": "頬", "complexity_tier": "T3", "furigana": "ほお", "sentence_source": "generated"}, {"text": "頬を軽くつねって、夢ではないと確かめた。", "target_word": "頬", "complexity_tier": "T3", "furigana": "ほお", "sentence_source": "generated"}, {"text": "彼は頬に虫が止まったのを感じた。", "target_word": "頬", "complexity_tier": "T3", "furigana": "ほお", "sentence_source": "generated"}], "morphological_forms": [{"form": "頬骨", "label": "派生"}, {"form": "頬杖", "label": "派生"}, {"form": "頬張る", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 風や手などが触れる顔の側面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 4 words above tier T3 (max 3): 木漏れ日 (Zipf 2.6), 照らす (Zipf 3.37), 黙々と (Zipf 3.25), 一体化 (Zipf 3.35)','sentence 1 above tier T3: 6 words above tier T3 (max 3): 苛烈 (Zipf 2.89), 寒風 (Zipf 2.18), 携え (Zipf 3.23), 駆け出し (Zipf 3.07), 逞し (Zipf 2.19), 凝縮 (Zipf 3.38)']::text[], 'a446fd76-121f-4288-b5cb-047371155a2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52119, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "顔の、口の横の、やわらかいところです。", "primary_collocate": null, "pronunciation": "ほお", "ipa": "hoː", "syllable_count": 2, "sentences": [{"text": "恥ずかしくて、頬が赤くなった。", "target_word": "頬", "complexity_tier": "T3", "furigana": "ほお", "sentence_source": "generated"}, {"text": "弟は頬をふくらませて、怒っている。", "target_word": "頬", "complexity_tier": "T3", "furigana": "ほお", "sentence_source": "generated"}, {"text": "彼女の頬は、りんごのように赤い。", "target_word": "頬", "complexity_tier": "T3", "furigana": "ほお", "sentence_source": "generated"}, {"text": "赤ちゃんの頬は、やわらかい。", "target_word": "頬", "complexity_tier": "T3", "furigana": "ほお", "sentence_source": "generated"}, {"text": "うれしくて、頬がゆるんだ。", "target_word": "頬", "complexity_tier": "T3", "furigana": "ほお", "sentence_source": "generated"}, {"text": "頬に涙の跡が残っていた。", "target_word": "頬", "complexity_tier": "T3", "furigana": "ほお", "sentence_source": "generated"}, {"text": "はずかしくて、頬が熱くなった。", "target_word": "頬", "complexity_tier": "T3", "furigana": "ほお", "sentence_source": "generated"}, {"text": "鏡を見ると、頬にえくぼがあった。", "target_word": "頬", "complexity_tier": "T3", "furigana": "ほお", "sentence_source": "generated"}, {"text": "彼女は頬に手を当てて、考えた。", "target_word": "頬", "complexity_tier": "T3", "furigana": "ほお", "sentence_source": "generated"}, {"text": "かわいい頬の子が、笑っている。", "target_word": "頬", "complexity_tier": "T3", "furigana": "ほお", "sentence_source": "generated"}], "morphological_forms": [{"form": "頬骨", "label": "派生"}, {"form": "頬杖", "label": "派生"}, {"form": "頬紅", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 気持ちが表れる顔の口の横", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T3: contains vocabulary far above tier T3: はずかしく (Zipf 1.95)']::text[], 'a446fd76-121f-4288-b5cb-047371155a2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52094, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "液体が表面を伝わって移動すること。また、そのようにして液体を移動させること。", "primary_collocate": null, "pronunciation": "つたう", "ipa": "tsɯtaɯ", "syllable_count": 3, "sentences": [{"text": "子供は躊躇いなくその表皮に歯を立て、甘酸っぱい果汁を唇に伝わせながら貪るように食べる。", "target_word": "伝わ", "complexity_tier": "T6", "furigana": "つたう", "sentence_source": "mined"}, {"text": "凛とした寒気が窓ガラスを伝い、室内の空気を凍てつかせようとしている。", "target_word": "伝い", "complexity_tier": "T6", "furigana": "つたう", "sentence_source": "mined"}, {"text": "雨のしずくが、窓を伝って落ちる。", "target_word": "伝って", "complexity_tier": "T3", "furigana": "つたう", "sentence_source": "generated"}, {"text": "汗が背中を伝うのを感じた。", "target_word": "伝う", "complexity_tier": "T3", "furigana": "つたう", "sentence_source": "generated"}, {"text": "水が壁を伝い、床にたまった。", "target_word": "伝い", "complexity_tier": "T3", "furigana": "つたう", "sentence_source": "generated"}, {"text": "雨水が屋根を伝って、庭に流れた。", "target_word": "伝って", "complexity_tier": "T3", "furigana": "つたう", "sentence_source": "generated"}, {"text": "涙が頬を伝って、落ちていった。", "target_word": "伝って", "complexity_tier": "T3", "furigana": "つたう", "sentence_source": "generated"}, {"text": "蛇口から水滴が、パイプを伝って落ちる。", "target_word": "伝って", "complexity_tier": "T3", "furigana": "つたう", "sentence_source": "generated"}, {"text": "川の水は、岩を伝って流れ落ちている。", "target_word": "伝って", "complexity_tier": "T3", "furigana": "つたう", "sentence_source": "generated"}, {"text": "雨が木の幹を伝い、根もとへ流れる。", "target_word": "伝い", "complexity_tier": "T3", "furigana": "つたう", "sentence_source": "generated"}], "morphological_forms": [{"form": "伝って", "label": "活用"}, {"form": "伝った", "label": "活用"}, {"form": "伝わせる", "label": "活用"}, {"form": "伝い歩き", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 液体が物の表面に沿って流れる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a446fd76-121f-4288-b5cb-047371155a2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52093, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "食べ物の汁などが、口や指の上をゆっくりと動いていくこと。", "primary_collocate": null, "pronunciation": "つたう", "ipa": "tsɯtaɯ", "syllable_count": 3, "sentences": [{"text": "肉の汁が、指を伝ってこぼれた。", "target_word": "伝って", "complexity_tier": "T3", "furigana": "つたう", "sentence_source": "generated"}, {"text": "ジュースが手首を伝って、服についた。", "target_word": "伝って", "complexity_tier": "T3", "furigana": "つたう", "sentence_source": "generated"}, {"text": "アイスが溶けて、指を伝い落ちた。", "target_word": "伝い", "complexity_tier": "T3", "furigana": "つたう", "sentence_source": "generated"}, {"text": "果汁が口の端を伝うのも気にせず、食べた。", "target_word": "伝う", "complexity_tier": "T3", "furigana": "つたう", "sentence_source": "generated"}, {"text": "スープが、スプーンを伝って落ちた。", "target_word": "伝って", "complexity_tier": "T3", "furigana": "つたう", "sentence_source": "generated"}, {"text": "桃の汁が、あごを伝っていった。", "target_word": "伝って", "complexity_tier": "T3", "furigana": "つたう", "sentence_source": "generated"}, {"text": "はちみつが、パンを伝って皿に垂れた。", "target_word": "伝って", "complexity_tier": "T3", "furigana": "つたう", "sentence_source": "generated"}, {"text": "ソースが、ナイフを伝って手に流れた。", "target_word": "伝って", "complexity_tier": "T3", "furigana": "つたう", "sentence_source": "generated"}, {"text": "トマトの汁が、腕を伝って肘まで流れた。", "target_word": "伝って", "complexity_tier": "T3", "furigana": "つたう", "sentence_source": "generated"}, {"text": "バターが溶けて、パンの端を伝った。", "target_word": "伝った", "complexity_tier": "T3", "furigana": "つたう", "sentence_source": "generated"}], "morphological_forms": [{"form": "伝って", "label": "活用"}, {"form": "伝った", "label": "活用"}, {"form": "伝い", "label": "活用"}, {"form": "伝わせる", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 食べ物の汁が指や口をゆっくり動く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a446fd76-121f-4288-b5cb-047371155a2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52224, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "パンやケーキなどを、オーブンで加熱して焼き上げる調理法。特に、小麦粉などをこねて発酵させた生地を焼くことを指す。", "primary_collocate": null, "pronunciation": "べーきんぐ", "ipa": "beːkiŋɡɯ", "syllable_count": 5, "sentences": [{"text": "現代の商業的なベーキングにおいては往々にして画一的な効率性が優先されがちであるが、彼が真に渇望するのは、サワードウ特有の繊細かつ複雑な酸味と、穀物本来が秘める深い旨みの極致である。", "target_word": "ベーキング", "complexity_tier": "T6", "furigana": "べーきんぐ", "sentence_source": "mined"}, {"text": "最終段階のベーキングでは、高温の蒸気と共に膨張した生地が、黄金色の硬質で脆いクラストを纏い、内部は瑞々しくも弾力に富んだクラムへと昇華する。", "target_word": "ベーキング", "complexity_tier": "T6", "furigana": "べーきんぐ", "sentence_source": "mined"}, {"text": "ベーキングは、温度と時間が大切だ。", "target_word": "ベーキング", "complexity_tier": "T3", "furigana": "べーきんぐ", "sentence_source": "generated"}, {"text": "ケーキのベーキングは、少し難しい。", "target_word": "ベーキング", "complexity_tier": "T3", "furigana": "べーきんぐ", "sentence_source": "generated"}, {"text": "ベーキングの時間は、四十分だった。", "target_word": "ベーキング", "complexity_tier": "T3", "furigana": "べーきんぐ", "sentence_source": "generated"}, {"text": "彼女はベーキングを習うために、教室に通った。", "target_word": "ベーキング", "complexity_tier": "T3", "furigana": "べーきんぐ", "sentence_source": "generated"}, {"text": "ベーキングの前に、生地を休ませておく。", "target_word": "ベーキング", "complexity_tier": "T3", "furigana": "べーきんぐ", "sentence_source": "generated"}, {"text": "ベーキングで、生地がふくらんだ。", "target_word": "ベーキング", "complexity_tier": "T3", "furigana": "べーきんぐ", "sentence_source": "generated"}, {"text": "生地を発酵させてから、ベーキングに進む。", "target_word": "ベーキング", "complexity_tier": "T3", "furigana": "べーきんぐ", "sentence_source": "generated"}, {"text": "ベーキングの技術を、本で学んだ。", "target_word": "ベーキング", "complexity_tier": "T3", "furigana": "べーきんぐ", "sentence_source": "generated"}], "morphological_forms": [{"form": "ベーキングパウダー", "label": "派生"}, {"form": "ベーキングシート", "label": "派生"}, {"form": "ベーキング用", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 生地をオーブンで焼き上げる調理の工程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a446fd76-121f-4288-b5cb-047371155a2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52223, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "パンをオーブンで焼くことです。", "primary_collocate": null, "pronunciation": "べーきんぐ", "ipa": "beːkiŋɡɯ", "syllable_count": 5, "sentences": [{"text": "父は日曜日にベーキングをする。", "target_word": "ベーキング", "complexity_tier": "T3", "furigana": "べーきんぐ", "sentence_source": "generated"}, {"text": "ベーキングで、パンを焼いた。", "target_word": "ベーキング", "complexity_tier": "T3", "furigana": "べーきんぐ", "sentence_source": "generated"}, {"text": "家でベーキングを楽しんでいる。", "target_word": "ベーキング", "complexity_tier": "T3", "furigana": "べーきんぐ", "sentence_source": "generated"}, {"text": "ベーキングが好きな母は、毎週パンを焼く。", "target_word": "ベーキング", "complexity_tier": "T3", "furigana": "べーきんぐ", "sentence_source": "generated"}, {"text": "パンのベーキングは、いい匂いがする。", "target_word": "ベーキング", "complexity_tier": "T3", "furigana": "べーきんぐ", "sentence_source": "generated"}, {"text": "今日は、ベーキングの日だ。", "target_word": "ベーキング", "complexity_tier": "T3", "furigana": "べーきんぐ", "sentence_source": "generated"}, {"text": "ベーキングをするとき、手を洗う。", "target_word": "ベーキング", "complexity_tier": "T3", "furigana": "べーきんぐ", "sentence_source": "generated"}, {"text": "弟とベーキングをして、パンを作った。", "target_word": "ベーキング", "complexity_tier": "T3", "furigana": "べーきんぐ", "sentence_source": "generated"}, {"text": "ベーキングが終わったら、パンを出してね。", "target_word": "ベーキング", "complexity_tier": "T3", "furigana": "べーきんぐ", "sentence_source": "generated"}, {"text": "ベーキングは、パンをオーブンで焼くことだ。", "target_word": "ベーキング", "complexity_tier": "T3", "furigana": "べーきんぐ", "sentence_source": "generated"}], "morphological_forms": [{"form": "ベーキングパウダー", "label": "派生"}, {"form": "ベーキングシート", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 家でパンをオーブンで焼くこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code