INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52238, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "食べ物や飲み物に含まれる、すっぱいと感じられる味。レモンや酢のような刺激的な味わい。", "primary_collocate": null, "pronunciation": "さんみ", "ipa": "sammi", "syllable_count": 3, "sentences": [{"text": "現代の商業的なベーキングにおいては往々にして画一的な効率性が優先されがちであるが、彼が真に渇望するのは、サワードウ特有の繊細かつ複雑な酸味と、穀物本来が秘める深い旨みの極致である。", "target_word": "酸味", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "数日かけて培養されたルヴァン種は、独特の酸味と芳醇な香りを纏い、パンの骨格を形成する。", "target_word": "酸味", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "酸味が強いレモンです。", "target_word": "酸味", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "このジュースは酸味が少ない。", "target_word": "酸味", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "コーヒーの酸味を楽しむ人が増えている。", "target_word": "酸味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酢を加えると、スープに軽い酸味が出る。", "target_word": "酸味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酸味が苦手な人には、このヨーグルトは少し強すぎる。", "target_word": "酸味", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "砂糖を入れたら、酸味がやわらいで飲みやすくなった。", "target_word": "酸味", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "トマトの酸味と甘みのバランスが、このソースの決め手だ。", "target_word": "酸味", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "熟したぶどうは酸味が穏やかで、深い甘みが口に広がる。", "target_word": "酸味", "complexity_tier": "T5", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 刺激的なすっぱい味わい", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T4: contains vocabulary far above tier T4: ベーキング (Zipf 1.24)']::text[], 'b35c09df-bb92-4395-8da7-5908bb39b13a') 