INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52237, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "食べ物の、すっぱい味のことです。", "primary_collocate": null, "pronunciation": "さんみ", "ipa": "sammi", "syllable_count": 3, "sentences": [{"text": "梅干しは酸味がある。", "target_word": "酸味", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "みかんの酸味が好きだ。", "target_word": "酸味", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "この料理は酸味が強いです。", "target_word": "酸味", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "レモンの酸味はとても強いです。", "target_word": "酸味", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "酸味のある食べ物が好きです。", "target_word": "酸味", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "酢の物には独特の酸味がある。", "target_word": "酸味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酸味があるので、水を足して飲んだ。", "target_word": "酸味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "このいちごは少し酸味が残っている。", "target_word": "酸味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酸味が強すぎて、子どもは食べられなかった。", "target_word": "酸味", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "この酢豚は、甘みの中にほのかな酸味がある。", "target_word": "酸味", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 食べ物のすっぱい味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b35c09df-bb92-4395-8da7-5908bb39b13a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED