INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52240, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "物体が変形した後、元の形に戻ろうとする性質や力。弾性。", "primary_collocate": null, "pronunciation": "だんりょく", "ipa": "daɲɾjokɯ", "syllable_count": 4, "sentences": [{"text": "指先を通じて伝わる生地の微妙な弾力や発酵の進行具合を唯一の羅針盤とし、彼は温度と湿度という変数を緻密に制御することで、微生物という目に見えぬパートナーとの静かなる対話を試みる。", "target_word": "弾力", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "最終段階のベーキングでは、高温の蒸気と共に膨張した生地が、黄金色の硬質で脆いクラストを纏い、内部は瑞々しくも弾力に富んだクラムへと昇華する。", "target_word": "弾力", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "ゴムは弾力がある。", "target_word": "弾力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "この生地は弾力が強い。", "target_word": "弾力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古いゴムは弾力を失う。", "target_word": "弾力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弾力のある素材を探している。", "target_word": "弾力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "パン生地をこねると、弾力が出てくる。", "target_word": "弾力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "スポンジの弾力を確かめるため、指で軽く押した。", "target_word": "弾力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "長く使うと、マットレスの弾力が少しずつ落ちる。", "target_word": "弾力", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "弾力に優れた素材は、靴の底によく使われる。", "target_word": "弾力", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 変形後に元へ戻る性質", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T4: contains vocabulary far above tier T4: ベーキング (Zipf 1.24)']::text[], 'b35c09df-bb92-4395-8da7-5908bb39b13a') ON CONFLICT (sense_id,