INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52239, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "ものを押したとき、元に戻ろうとする力のこと。", "primary_collocate": null, "pronunciation": "だんりょく", "ipa": "daɲɾjokɯ", "syllable_count": 4, "sentences": [{"text": "ほっぺたは弾力がある。", "target_word": "弾力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "グミは弾力があります。", "target_word": "弾力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "もちの弾力が好きです。", "target_word": "弾力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "指で押すと弾力を感じる。", "target_word": "弾力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "ボールを押すと、弾力で手が戻される。", "target_word": "弾力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "赤ちゃんの肌は、触ると弾力がある。", "target_word": "弾力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "この枕は弾力があって、寝心地がいい。", "target_word": "弾力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年を取ると、肌の弾力は少なくなる。", "target_word": "弾力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "麺の弾力が強いほど、噛みごたえがある。", "target_word": "弾力", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "弾力のあるタイヤは、道の凹凸を吸収する。", "target_word": "弾力", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 押すと戻ろうとする力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b35c09df-bb92-4395-8da7-5908bb39b13a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnin