INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36397, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "その場の雰囲気や、周りの人の何となくの感じ。目に見えないが、みんながなんとなく感じる様子。", "primary_collocate": null, "pronunciation": "くうき", "ipa": "kɯːki", "syllable_count": 3, "sentences": [{"text": "修業の途上にある若きパン職人は、夜明け前の凛とした空気が張り詰めるアトリエにて、野生の酵母が織りなす微細かつ劇的な化学反応と黙々と格闘していた。", "target_word": "空気", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "凛とした寒気が窓ガラスを伝い、室内の空気を凍てつかせようとしている。", "target_word": "空気", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "凍てつく空気の中、ボタンを一つひとつ留める仕草には、未知の領域へ挑む戦士のような厳粛ささえ漂っていた。", "target_word": "空気", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "部屋の空気が重い。", "target_word": "空気", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "教室の空気が変わった。", "target_word": "空気", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会場には明るい空気が流れていた。", "target_word": "空気", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "試合の前、緊張した空気に包まれた。", "target_word": "空気", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "その店の落ち着いた空気が好きだ。", "target_word": "空気", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "彼が来ると、部屋の空気がやわらいだ。", "target_word": "空気", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "静まり返った会議室には、重苦しい空気が漂っていた。", "target_word": "空気", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | その場に漂う雰囲気", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 張り詰める (Zipf 1.07)','sentence 1 above tier T2: contains vocabulary far above tier T2: 凍てつか (Zipf 1.03)','sentence 2 above tier T2: contains vocabulary far above tier T2: 凍てつく (Zipf 2.35)','sentence 8 above tier T2: contains vocabulary far above tier T2: やわらい (Zipf 1.59)','sentence 9 above tier T2: contains vocabulary far above tier T2: 静まり返っ (Zipf 2.4)']::text[], 'b35c09df-bb92-4395-8da7-5908bb39b13a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36396, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "周りの人の気持ちや、その場の感じのこと。", "primary_collocate": "読む", "pronunciation": "くうき", "ipa": "kɯːki", "syllable_count": 3, "sentences": [{"text": "空気を読もう。", "target_word": "空気", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "彼は空気が読めない。", "target_word": "空気", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "空気を読んで、黙っていた。", "target_word": "空気", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "その場の空気に逆らうのは難しい。", "target_word": "空気", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空気を壊したくなくて、何も言えなかった。", "target_word": "空気", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周りの空気に合わせて、笑顔で答えた。", "target_word": "空気", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "彼女の一言で、気まずい空気が流れた。", "target_word": "空気", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日本では、空気を読む力が大切だと言われる。", "target_word": "空気", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "みんなが反対する空気だったので、私も手を挙げなかった。", "target_word": "空気", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "空気が読めない人だと思われたくない。", "target_word": "空気", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 周りの人の気持ちの流れ", "collocate_grounding": {"status": "no_source", "reason": "grounding deferred for this language — no frequency source"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b35c09df-bb92-4395-8da7-5908bb39b13a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.valida