INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36967, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "「本来」は、あるものが初めからそうであること、または当然そうあるべき状態を表す語です。", "primary_collocate": null, "pronunciation": "ほんらい", "ipa": "honɾai", "syllable_count": 4, "sentences": [{"text": "現代の商業的なベーキングにおいては往々にして画一的な効率性が優先されがちであるが、彼が真に渇望するのは、サワードウ特有の繊細かつ複雑な酸味と、穀物本来が秘める深い旨みの極致である。", "target_word": "本来", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "苛烈な寒風が頬を打つ外の世界へと、無垢な好奇心を携えて駆け出していくその背中には、人間が本来備えている、過酷な環境をも楽しみへと変貌させる逞しさが凝縮されていたのである。", "target_word": "本来", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "本来の姿に戻る。", "target_word": "本来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "これが本来の目的です。", "target_word": "本来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "本来あるべき形を考えた。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "スマホは本来、連絡のための道具だ。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生の本来の仕事は勉強だ。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本来なら、今日は休みのはずだった。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本来の味を残すため、塩だけで焼いた。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "この機械は、本来の性能を十分に発揮していない。", "target_word": "本来", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 当然そうあるべき状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: ベーキング (Zipf 1.24), 極致 (Zipf 2.48)','sentence 1 above tier T2: contains vocabulary far above tier T2: 寒風 (Zipf 2.18), 逞し (Zipf 2.19)']::text[], 'b35c09df-bb92-4395-8da7-5908bb39b13a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36966, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "「本来」は、「もともと」という意味です。", "primary_collocate": null, "pronunciation": "ほんらい", "ipa": "honɾai", "syllable_count": 4, "sentences": [{"text": "本来、私は静かな人です。", "target_word": "本来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "彼は本来、やさしい人だ。", "target_word": "本来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "この店は本来、古い倉庫だった。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "この言葉は本来、別の意味だった。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "この道具は本来、農作業のために作られた。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本来は海だった場所が、今は町になっている。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "彼女は本来、人前で話すのが苦手だ。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "この祭りは本来、秋の収穫を祝う行事だった。", "target_word": "本来", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "本来は夏の果物だが、今は冬も買える。", "target_word": "本来", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "日本語の「ありがとう」は本来、めったにないという意味だった。", "target_word": "本来", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | もともとの意味の語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b35c09df-bb92-4395-8da7-5908bb39b13a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36075, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事や機械の動きを、自分の思うように調整すること。", "primary_collocate": null, "pronunciation": "せいぎょ", "ipa": "seːɡjo", "syllable_count": 3, "sentences": [{"text": "指先を通じて伝わる生地の微妙な弾力や発酵の進行具合を唯一の羅針盤とし、彼は温度と湿度という変数を緻密に制御することで、微生物という目に見えぬパートナーとの静かなる対話を試みる。", "target_word": "制御", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "水温と室温をミリ単位で制御し、小麦粉と水のみを混ぜ合わせる行為は、単なる調理の域を超え、微生物の生態系を育む科学的な実験とも呼応する。", "target_word": "制御", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "機械を制御します。", "target_word": "制御", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "感情を制御するのは難しい。", "target_word": "制御", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "このソフトで部屋の温度を制御できる。", "target_word": "制御", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "制御が効かなくなった車は、壁にぶつかった。", "target_word": "制御", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "コンピューターが信号を制御している。", "target_word": "制御", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "ロボットの動きを制御する。", "target_word": "制御", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "制御できない怒りが、彼を苦しめていた。", "target_word": "制御", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "速度を自動で制御する装置が、事故を防いでくれる。", "target_word": "制御", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [{"form": "制御する", "label": "活用"}, {"form": "制御できる", "label": "活用"}, {"form": "制御される", "label": "活用"}, {"form": "制御した", "label": "活用"}], "register": "plain", "sense_fingerprint": "名詞 | 動きを思い通り調整する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: 7 words above tier T2 (max 3): 指先 (Zipf 3.6), 弾力 (Zipf 3.23), 羅針盤 (Zipf 3.09), 変数 (Zipf 3.63), 緻密 (Zipf 3.25), 微生物 (Zipf 3.52)','sentence 1 above tier T2: 7 words above tier T2 (max 3): 水温 (Zipf 3.22), 室温 (Zipf 3.3), 小麦粉 (Zipf 3.59), 混ぜ合わ (Zipf 2.89), 微生物 (Zipf 3.52), 育む (Zipf 3.02)']::text[], 'b35c09df-bb92-4395-8da7-5908bb39b13a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52212, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "「凛と」は、態度や雰囲気が引き締まっていて、気高く、美しい様子を表す副詞です。", "primary_collocate": null, "pronunciation": "りんと", "ipa": "ɾinto", "syllable_count": 3, "sentences": [{"text": "修業の途上にある若きパン職人は、夜明け前の凛とした空気が張り詰めるアトリエにて、野生の酵母が織りなす微細かつ劇的な化学反応と黙々と格闘していた。", "target_word": "凛とした", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "凛とした寒気が窓ガラスを伝い、室内の空気を凍てつかせようとしている。", "target_word": "凛とした", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "凛とした朝の空気だ。", "target_word": "凛とした", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "凛とした声で答えた。", "target_word": "凛とした", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "彼女は凛と立っていた。", "target_word": "凛と", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "凛とした冬の朝が来た。", "target_word": "凛とした", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "凛と咲く花に目を奪われた。", "target_word": "凛と", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凛とした表情で、彼は前を向いた。", "target_word": "凛とした", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神社の凛とした静けさの中で手を合わせた。", "target_word": "凛とした", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "凛と張りつめた空気の中で、試合が始まった。", "target_word": "凛と", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "副詞 | 引き締まり気高く美しい様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T4: contains vocabulary far above tier T4: 張り詰める (Zipf 1.07)','sentence 1 above tier T4: contains vocabulary far above tier T4: 凍てつか (Zipf 1.03)']::text[], 'b35c09df-bb92-4395-8da7