INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52211, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "「凛と」は、かっこよくて、しっかりしている様子を表す言葉です。", "primary_collocate": null, "pronunciation": "りんと", "ipa": "ɾinto", "syllable_count": 3, "sentences": [{"text": "先生は凛と話した。", "target_word": "凛と", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "彼女は凛としている。", "target_word": "凛と", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "凛とした人になりたい。", "target_word": "凛とした", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "凛と胸を張る。", "target_word": "凛と", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "彼女の凛とした姿がかっこいい。", "target_word": "凛とした", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凛とした態度で、堂々と発表した。", "target_word": "凛とした", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凛と背筋を伸ばした姿に、みんなが見とれた。", "target_word": "凛と", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凛と前を向いて歩く姿は、とても強く見えた。", "target_word": "凛と", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "かっこよくて凛としたあの先輩にあこがれている。", "target_word": "凛とした", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "たとえ困っても、凛とした気持ちを失いたくない。", "target_word": "凛とした", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "副詞 | かっこよくしっかりした様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b35c09df-bb92-4395-8da7-5908bb39b13a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors