INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36396, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "空気", "is_correct": true, "explanation": "「空気」が聞こえた語そのものです。"}, {"text": "勇気", "is_correct": false, "explanation": "「ゆうき」は音が一拍だけ違う別の語です。"}, {"text": "風紀", "is_correct": false, "explanation": "「ふうき」は音が一拍だけ違う別の語です。"}, {"text": "動機", "is_correct": false, "explanation": "「どうき」は音が一拍だけ違う別の語です。"}, {"text": "空母", "is_correct": false, "explanation": "「くうぼ」は音が一拍だけ違う別の語です。"}], "explanations": {"空気": "「空気」が聞こえた語そのものです。", "勇気": "「ゆうき」は音が一拍だけ違う別の語です。", "風紀": "「ふうき」は音が一拍だけ違う別の語です。", "動機": "「どうき」は音が一拍だけ違う別の語です。", "空母": "「くうぼ」は音が一拍だけ違う別の語です。"}, "sentence_index": null, "correct_answer": "空気"}, "level_3": {"options": [{"text": "空気", "is_correct": true, "explanation": "「空気」を入れると周りの気持ちを察する「読む」と自然に結び付く。"}, {"text": "皿", "is_correct": false, "explanation": "「皿」は形は合うが、この文では意味が合わない。"}, {"text": "机", "is_correct": false, "explanation": "「机」は形は合うが、この文では意味が合わない。"}, {"text": "靴", "is_correct": false, "explanation": "「靴」は形は合うが、この文では意味が合わない。"}], "explanations": {"空気": "「空気」を入れると周りの気持ちを察する「読む」と自然に結び付く。", "皿": "「皿」は形は合うが、この文では意味が合わない。", "机": "「机」は形は合うが、この文では意味が合わない。", "靴": "「靴」は形は合うが、この文では意味が合わない。"}, "sentence_index": 0, "correct_answer": "空気"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "空気とは、雨の日にさす傘のことだ。", "explanation": "「空気」は人々の気持ちの流れで、傘ではない。"}, {"text": "彼は空気を食べて、周りの気持ちを知った。", "explanation": "「空気」を「食べる」ことで気持ちを知る使い方は誤り。"}, {"text": "空気を読むのは、足で数えることだ。", "explanation": "「空気を読む」は気持ちを察することで、数えることではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3097235-543a-4102-b988-aa50a91179a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, valid